//! Owned observed reader-open outcome. It is not file payload, stamp, source
//! acquisition or EOF. Aliases retain exact failure text/credit, never reformat
//! or deep-copy it during persistent fact insertion.
use super::*;use super::path_presence::ImmutableFactValue;
use dm_preprocess::source_arena_credit::{SourceArenaCredit,SourceArenaWork};use std::sync::Arc;
#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]pub(crate) enum OriginalOpenFailureKind{Missing,Denied,NotDirectory,InvalidPath,SharingDenied}
impl OriginalOpenFailureKind{fn from_io(error:&io::Error)->io::Result<Self>{if !super::original_source_open_failure(error){return Err(io::Error::new(io::ErrorKind::InvalidData,"operational IO cannot become a source-open observation"))}if cfg!(windows)&&matches!(error.raw_os_error(),Some(32|33)){return Ok(Self::SharingDenied)}match error.kind(){io::ErrorKind::NotFound=>Ok(Self::Missing),io::ErrorKind::PermissionDenied=>Ok(Self::Denied),io::ErrorKind::NotADirectory=>Ok(Self::NotDirectory),io::ErrorKind::InvalidInput=>Ok(Self::InvalidPath),_=>Err(io::Error::new(io::ErrorKind::InvalidData,"operational IO cannot become a source-open observation"))}}fn io(self)->io::ErrorKind{match self{Self::Missing=>io::ErrorKind::NotFound,Self::Denied=>io::ErrorKind::PermissionDenied,Self::NotDirectory=>io::ErrorKind::NotADirectory,Self::InvalidPath=>io::ErrorKind::InvalidInput,Self::SharingDenied=>io::ErrorKind::Other}}}
pub struct Failure{kind:OriginalOpenFailureKind,raw:Option<i32>,message:String,credit:Option<SourceArenaCredit>}
pub enum OriginalReadOpenStatus{Readable,Failed(Option<Arc<Failure>>)}
impl Clone for OriginalReadOpenStatus{fn clone(&self)->Self{match self{Self::Readable=>Self::Readable,Self::Failed(value)=>Self::Failed(value.clone())}}}
impl Drop for OriginalReadOpenStatus{fn drop(&mut self){if let Self::Failed(owner)=self{if let Some(owner)=owner.take(){if let Some(payload)=Arc::into_inner(owner){drop(payload)}}}}}
impl std::fmt::Debug for OriginalReadOpenStatus{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{match self{Self::Readable=>f.write_str("Readable"),Self::Failed(value)=>{let value=value.as_ref().expect("actual open failure");f.debug_struct("SourceOpenFailed").field("kind",&value.kind).field("raw",&value.raw).field("message",&value.message).finish()}}}}
impl PartialEq for OriginalReadOpenStatus{fn eq(&self,other:&Self)->bool{match(self,other){(Self::Readable,Self::Readable)=>true,(Self::Failed(a),Self::Failed(b))=>{let a=a.as_ref().unwrap();let b=b.as_ref().unwrap();a.kind==b.kind&&a.raw==b.raw&&a.message==b.message},_=>false}}}impl Eq for OriginalReadOpenStatus{}
#[derive(Serialize,Deserialize)]enum Wire{Readable,Failed{kind:OriginalOpenFailureKind,raw:Option<i32>,message:String}}
impl Serialize for OriginalReadOpenStatus{fn serialize<S:serde::Serializer>(&self,s:S)->Result<S::Ok,S::Error>{#[derive(Serialize)]enum Borrow<'a>{Readable,Failed{kind:OriginalOpenFailureKind,raw:Option<i32>,message:&'a str}}match self{Self::Readable=>Borrow::Readable.serialize(s),Self::Failed(value)=>{let value=value.as_ref().unwrap();Borrow::Failed{kind:value.kind,raw:value.raw,message:&value.message}.serialize(s)}}}}
impl<'de>Deserialize<'de> for OriginalReadOpenStatus{fn deserialize<D:serde::Deserializer<'de>>(d:D)->Result<Self,D::Error>{Ok(match Wire::deserialize(d)?{Wire::Readable=>Self::Readable,Wire::Failed{kind,raw,message}=>Self::Failed(Some(Arc::new(Failure{kind,raw,message,credit:None})))})}}
impl ImmutableFactValue for OriginalReadOpenStatus{fn visit_fact_storage(&self,visit:&mut dyn FnMut(usize,usize,usize)){if let Self::Failed(value)=self{let value=value.as_ref().unwrap();visit(Arc::as_ptr(value)as usize,std::mem::size_of::<Failure>()+2*std::mem::size_of::<usize>(),std::mem::size_of::<Failure>()+2*std::mem::size_of::<usize>());visit(value.message.as_ptr()as usize,value.message.len(),value.message.capacity());if let Some(credit)=&value.credit{credit.visit_storage(&mut |p,n|visit(p,n,n));}}}}
struct Text<'a>{text:String,credit:SourceArenaCredit,work:&'a dyn SourceArenaWork,first:Option<io::Error>}
impl std::fmt::Write for Text<'_>{fn write_str(&mut self,s:&str)->std::fmt::Result{let result=(||{let needed=self.text.len().checked_add(s.len()).ok_or(io::ErrorKind::OutOfMemory)?;if needed>self.text.capacity(){let target=needed.max(self.text.capacity().saturating_mul(2));let bound=target.checked_mul(4).ok_or(io::ErrorKind::OutOfMemory)?;self.work.grow(&mut self.credit,bound)?;let old=self.text.capacity();self.text.try_reserve_exact(target-self.text.len()).map_err(|e|io::Error::new(io::ErrorKind::OutOfMemory,e))?;if self.text.capacity()>bound{return Err(io::ErrorKind::OutOfMemory.into())}self.work.shrink(&mut self.credit,bound-self.text.capacity().checked_sub(old).ok_or(io::ErrorKind::InvalidData)?)?;}self.text.push_str(s);Ok(())})();match result{Ok(())=>Ok(()),Err(error)=>{if self.first.is_none(){self.first=Some(error)}Err(std::fmt::Error)}}}}
impl OriginalReadOpenStatus{
 pub(crate) fn capture_using(error:&io::Error,work:&dyn SourceArenaWork)->io::Result<Self>{work.checkpoint()?;let kind=OriginalOpenFailureKind::from_io(error)?;let fixed=std::mem::size_of::<Failure>()+2*std::mem::size_of::<usize>();let mut text=Text{text:String::new(),credit:work.reserve(fixed)?,work,first:None};let formatted=std::fmt::write(&mut text,format_args!("{error}"));if let Some(actual)=text.first.take(){return Err(actual)}formatted.map_err(|_|io::Error::new(io::ErrorKind::InvalidData,"open error formatter failed without its actual error"))?;Ok(Self::Failed(Some(Arc::new(Failure{kind,raw:error.raw_os_error(),message:text.text,credit:Some(text.credit)}))))}
 /// Non-admitted transient validation DATA. It is never retained as a new
 /// admitted capture: unchanged facts keep their already-funded original owner.
 pub(crate) fn observed(error:&io::Error)->io::Result<Self>{Ok(Self::Failed(Some(Arc::new(Failure{kind:OriginalOpenFailureKind::from_io(error)?,raw:error.raw_os_error(),message:error.to_string(),credit:None}))))}
 pub(crate) fn is_readable(&self)->bool{matches!(self,Self::Readable)}
 /// Replay retains the admitted failure string by alias, not by a hidden deep
 /// copy. OS errors preserve the actual raw code/kind without allocating text.
 pub(crate) fn error_using(&self,work:&dyn SourceArenaWork)->io::Result<io::Error>{let Self::Failed(value)=self else{return Err(io::ErrorKind::InvalidInput.into())};let value=value.as_ref().unwrap();if let Some(raw)=value.raw{let error=io::Error::from_raw_os_error(raw);if OriginalOpenFailureKind::from_io(&error)?!=value.kind||error.to_string()!=value.message{return Err(io::Error::new(io::ErrorKind::InvalidData,"recorded OS-open cause cannot be replayed faithfully on this host"))}return Ok(error)}let credit=work.reserve(std::mem::size_of::<ReplayedFailure>()+4*std::mem::size_of::<usize>())?;Ok(io::Error::new(value.kind.io(),ReplayedFailure{status:self.clone(),_credit:credit}))}
}
struct ReplayedFailure{status:OriginalReadOpenStatus,_credit:SourceArenaCredit}
impl std::fmt::Display for ReplayedFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{let OriginalReadOpenStatus::Failed(value)=&self.status else{return Err(std::fmt::Error)};f.write_str(&value.as_ref().unwrap().message)}}
impl std::error::Error for ReplayedFailure{}

impl std::fmt::Debug for ReplayedFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.debug_struct("ReplayedSourceOpenFailure").field("status",&self.status).finish()}}
